mkitem!{mkstruct!{# [doc = " Representation of a borrowed C string."] # [doc = ""] # [doc = " This type represents a borrowed reference to a nul-terminated"] # [doc = " array of bytes. It can be constructed safely from a <code>&[[u8]]</code>"] # [doc = " slice, or unsafely from a raw `*const c_char`. It can be expressed as a"] # [doc = " literal in the form `c\"Hello world\"`."] # [doc = ""] # [doc = " The `CStr` can then be converted to a Rust <code>&[str]</code> by performing"] # [doc = " UTF-8 validation, or into an owned `CString`."] # [doc = ""] # [doc = " `&CStr` is to `CString` as <code>&[str]</code> is to `String`: the former"] # [doc = " in each pair are borrowed references; the latter are owned"] # [doc = " strings."] # [doc = ""] # [doc = " Note that this structure does **not** have a guaranteed layout (the `repr(transparent)`"] # [doc = " notwithstanding) and should not be placed in the signatures of FFI functions."] # [doc = " Instead, safe wrappers of FFI functions may leverage [`CStr::as_ptr`] and the unsafe"] # [doc = " [`CStr::from_ptr`] constructor to provide a safe interface to other consumers."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Inspecting a foreign C string:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ffi::CStr;"] # [doc = " use std::os::raw::c_char;"] # [doc = ""] # [doc = " # /* Extern functions are awkward in doc comments - fake it instead"] # [doc = " extern \"C\" { fn my_string() -> *const c_char; }"] # [doc = " # */ unsafe extern \"C\" fn my_string() -> *const c_char { c\"hello\".as_ptr() }"] # [doc = ""] # [doc = " unsafe {"] # [doc = "     let slice = CStr::from_ptr(my_string());"] # [doc = "     println!(\"string buffer size without nul terminator: {}\", slice.to_bytes().len());"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Passing a Rust-originating C string:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ffi::CStr;"] # [doc = " use std::os::raw::c_char;"] # [doc = ""] # [doc = " fn work(data: &CStr) {"] # [doc = "     unsafe extern \"C\" fn work_with(s: *const c_char) {}"] # [doc = "     unsafe { work_with(data.as_ptr()) }"] # [doc = " }"] # [doc = ""] # [doc = " let s = c\"Hello world!\";"] # [doc = " work(&s);"] # [doc = " ```"] # [doc = ""] # [doc = " Converting a foreign C string into a Rust `String`:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ffi::CStr;"] # [doc = " use std::os::raw::c_char;"] # [doc = ""] # [doc = " # /* Extern functions are awkward in doc comments - fake it instead"] # [doc = " extern \"C\" { fn my_string() -> *const c_char; }"] # [doc = " # */ unsafe extern \"C\" fn my_string() -> *const c_char { c\"hello\".as_ptr() }"] # [doc = ""] # [doc = " fn my_string_safe() -> String {"] # [doc = "     let cstr = unsafe { CStr::from_ptr(my_string()) };"] # [doc = "     // Get a copy-on-write Cow<'_, str>, then extract the"] # [doc = "     // allocated String (or allocate a fresh one if needed)."] # [doc = "     cstr.to_string_lossy().into_owned()"] # [doc = " }"] # [doc = ""] # [doc = " println!(\"string: {}\", my_string_safe());"] # [doc = " ```"] # [doc = ""] # [doc = " [str]: prim@str \"str\""] # [derive (PartialEq , Eq , Hash)] # [stable (feature = "core_c_str" , since = "1.64.0")] # [rustc_diagnostic_item = "cstr_type"] # [rustc_has_incoherent_inherent_impls] # [lang = "CStr"] # [repr (transparent)] pub struct CStr { inner : [c_char] , }}}
mkitem!{mkenum!{# [doc = " An error indicating that a nul byte was not in the expected position."] # [doc = ""] # [doc = " The slice used to create a [`CStr`] must have one and only one nul byte,"] # [doc = " positioned at the end."] # [doc = ""] # [doc = " This error is created by the [`CStr::from_bytes_with_nul`] method."] # [doc = " See its documentation for more."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::ffi::{CStr, FromBytesWithNulError};"] # [doc = ""] # [doc = " let _: FromBytesWithNulError = CStr::from_bytes_with_nul(b\"f\\0oo\").unwrap_err();"] # [doc = " ```"] # [derive (Clone , Copy , PartialEq , Eq , Debug)] # [stable (feature = "core_c_str" , since = "1.64.0")] pub enum FromBytesWithNulError { # [doc = " Data provided contains an interior nul byte at byte `position`."] InteriorNul { # [doc = " The position of the interior nul byte."] position : usize , } , # [doc = " Data provided is not nul terminated."] NotNulTerminated , }}}
mkitem!{mkimpl!{# [stable (feature = "frombyteswithnulerror_impls" , since = "1.17.0")] impl fmt :: Display for FromBytesWithNulError { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { match self { Self :: InteriorNul { position } => { write ! (f , "data provided contains an interior nul byte at byte position {position}") } Self :: NotNulTerminated => write ! (f , "data provided is not nul terminated") , } } }}}
